## ---- 01: Identity Checks  (qmd line 27) ---------------------------------------------

check_identities <- function(proj, tol = 1e-6) {
  # proj: list of matrices B, I, P, VP, D_gr, R, F_svc, F_gty, CF_wl
  # each [n_paths x n_months + 1] for B, [n_paths x n_months] for others
  bal_err <- abs(proj$B[, -1] -
                 (proj$B[, -ncol(proj$B)] - proj$P - proj$VP - proj$D_gr))
  bal_rel <- bal_err / pmax(proj$B[, -ncol(proj$B)], 1)
  max_bal_err <- max(bal_rel)

  cash_err <- abs((proj$I + proj$P + proj$VP + proj$R) -
                  (proj$CF_wl + proj$F_svc + proj$F_gty))
  cash_rel <- cash_err / pmax(proj$I + 1, 1)
  max_cash_err <- max(cash_rel)

  list(max_balance_error = max_bal_err,
       max_cash_error    = max_cash_err,
       pass              = max_bal_err < tol && max_cash_err < tol)
}


## ---- 02: Identity Tests (User Helpers)  (qmd line 245) -------------------------------

# Helpers: balance-recursion and cash-conservation checks (didactic)
check_identities <- function(proj, tol = 1e-6) {
  bal_err <- abs(proj$B[, -1] -
                 (proj$B[, -ncol(proj$B)] - proj$P -
                  proj$VP - proj$D_gr))
  bal_rel <- bal_err / pmax(proj$B[, -ncol(proj$B)], 1)
  cash_err <- abs((proj$I + proj$P + proj$VP + proj$R) -
                  (proj$CF_wl + proj$F_svc + proj$F_gty))
  list(
    max_bal_rel  = max(bal_rel),
    max_cash_rel = max(cash_err / pmax(proj$I, 1)),
    pass         = max(bal_rel) < tol && max(cash_err) < tol
  )
}


## ---- 03: Deterministic Cross-Check via `oasr::project_cashflows`  (qmd line 264) -----

# Run oasr with zero prepay/default to compare against closed form
deterministic_check <- function(asset_data, tol = 1e-8) {
  prepay_zero <- prepayment_model(type = "cpr_cdr",
                                   base_cpr = 0, base_cdr = 0)
  n <- asset_data$term[1]
  flat_rates <- list(yield_paths = list("10" = matrix(0.0825, 1, n)))
  cv <- calculate_credit_vectors(asset_data, flat_rates, prepay_zero)
  cf <- project_cashflows(asset_data, cv)[[1]][, , 1]

  pmt <- asset_data$balance * (asset_data$wac / 12) /
         (1 - (1 + asset_data$wac / 12)^(-n))

  # oasr cashflow columns: 2 = scheduled principal, 7 = interest
  payment <- cf[, 2] + cf[, 7]
  max(abs(payment[seq_len(n - 1)] - pmt)) < tol
}


## ---- 04: Servicer Tape Reconciliation  (qmd line 285) --------------------------------

reconcile_servicer <- function(engine_cf, servicer_cf) {
  diff <- engine_cf - servicer_cf
  data.frame(
    cumulative_bps = sum(diff) / sum(servicer_cf) * 10000,
    monthly_max_bps = max(abs(diff)) / mean(servicer_cf) * 10000,
    months_outside_tol = sum(abs(diff) / mean(servicer_cf) > 0.0005)
  )
}


## ---- 05: WAL, Macaulay Duration, Convexity  (qmd line 298) ---------------------------

compute_wal <- function(cf_path, principal_only = TRUE) {
  if (principal_only) cf_path <- cf_path$P + cf_path$VP + cf_path$R
  t <- seq_along(cf_path) / 12
  sum(t * cf_path) / sum(cf_path)
}

macaulay_duration <- function(cf, t, ytm) {
  df <- (1 + ytm/12)^(-t)
  sum(t * cf * df) / sum(cf * df)
}

modified_convexity <- function(cf, t, ytm) {
  df <- (1 + ytm/12)^(-t)
  sum(t * (t + 1) * cf * df) / sum(cf * df) / (1 + ytm/12)^2
}


## ---- 06: Market-Platform Output Comparison  (qmd line 318) ---------------------------

platform_compare <- function(engine_clean, platform_clean,
                             engine_wal, platform_wal) {
  data.frame(
    clean_diff_cents = (engine_clean - platform_clean) * 100,
    wal_diff_years   = engine_wal - platform_wal,
    pass             = abs(engine_clean - platform_clean) < 0.05 &&
                       abs(engine_wal - platform_wal) < 0.05
  )
}


## ---- 07: Run-Time Profiling  (qmd line 332) ------------------------------------------

library(profvis)

library(oasr)

# The pool bundled with oasr, and a flat rate scenario to profile against
asset_data <- oasr::sample_abs_data
n_months   <- 360
rate_paths <- list(yield_paths = list(
  "10" = matrix(0.0825, nrow = 100, ncol = n_months)))

prepay <- prepayment_model(type = "cpr_cdr", base_cpr = 0.06, base_cdr = 0.01)
cv     <- calculate_credit_vectors(asset_data, rate_paths, prepay)

p <- profvis({
  cf_pool <- project_cashflows(asset_data, cv, n_periods = n_months)
})
# print(p) opens the interactive flame graph


## ---- 08: Dashboard  (qmd line 354) ---------------------------------------------------

print_diagnostics <- function(pool_id, run_results) {
  cat("Pool:", pool_id, "\n")
  cat("Identity max rel err:",
      formatC(run_results$id_max, format = "e"), "\n")
  cat("Servicer recon (bps cumulative):",
      round(run_results$svc_bps, 1), "\n")
  cat("Platform clean diff (cents):",
      round(run_results$platform_diff, 2), "\n")
  cat("WAL:", round(run_results$wal, 2), "yrs\n")
  cat("Run time:", round(run_results$elapsed, 2), "s\n")
}


